-- Task 10 phase 2.  This migration deliberately has no external executor.
-- Source publication and entitlement writes share one finite lock set.
CREATE FUNCTION control_plane.membership_access_source_set_fence(p_exclusive boolean DEFAULT false) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ BEGIN
 IF p_exclusive THEN PERFORM pg_advisory_xact_lock(8006); ELSE PERFORM pg_advisory_xact_lock_shared(8006); END IF;
END $$;

DROP TRIGGER entitlement_publication_fence ON control_plane.entitlements;
DROP TRIGGER entitlement_alias_publication_fence ON control_plane.entitlement_evidence_aliases;
CREATE FUNCTION control_plane.entitlement_source_set_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,control_plane AS $$
DECLARE m uuid:=COALESCE(NEW.mapping_id,OLD.mapping_id); e uuid:=COALESCE(NEW.id,OLD.id); BEGIN
 IF TG_OP<>'DELETE' AND EXISTS (SELECT 1 FROM membership_access_sources s WHERE s.publication_state='published' AND NOT EXISTS (SELECT 1 FROM membership_access_source_targets t WHERE t.source_id=s.id AND t.mapping_id=m) AND (s.mapping_id=m OR EXISTS (SELECT 1 FROM membership_access_source_selector_aliases sa WHERE sa.source_id=s.id AND EXISTS (SELECT 1 FROM entitlement_evidence_aliases ea WHERE ea.entitlement_id=e AND ea.evidence_kind=sa.selector_kind AND ea.fingerprint_key_id=sa.fingerprint_key_id AND ea.fingerprint=sa.fingerprint)))) THEN RAISE EXCEPTION 'entitlement matches a published revocation source'; END IF;
 RETURN COALESCE(NEW,OLD); END $$;
CREATE TRIGGER entitlement_source_set_guard BEFORE INSERT OR UPDATE OR DELETE ON control_plane.entitlements FOR EACH ROW EXECUTE FUNCTION control_plane.entitlement_source_set_guard();
CREATE FUNCTION control_plane.entitlement_alias_source_set_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,control_plane AS $$ DECLARE m uuid; BEGIN
 PERFORM membership_access_source_set_fence(false); IF TG_OP='DELETE' THEN RETURN OLD; END IF; SELECT mapping_id INTO m FROM entitlements WHERE id=NEW.entitlement_id;
 IF EXISTS(SELECT 1 FROM membership_access_sources s WHERE s.publication_state='published' AND NOT EXISTS(SELECT 1 FROM membership_access_source_targets t WHERE t.source_id=s.id AND t.mapping_id=m) AND NOT EXISTS(SELECT 1 FROM membership_access_source_selector_aliases sa WHERE sa.source_id=s.id AND NOT ((sa.selector_kind=NEW.evidence_kind AND sa.fingerprint_key_id=NEW.fingerprint_key_id AND sa.fingerprint=NEW.fingerprint) OR EXISTS(SELECT 1 FROM entitlement_evidence_aliases ea WHERE ea.entitlement_id=NEW.entitlement_id AND ea.evidence_kind=sa.selector_kind AND ea.fingerprint_key_id=sa.fingerprint_key_id AND ea.fingerprint=sa.fingerprint)))) THEN RAISE EXCEPTION 'entitlement alias would make published source fanout incomplete'; END IF; RETURN NEW; END $$;
CREATE TRIGGER entitlement_alias_source_set_guard BEFORE INSERT OR UPDATE OR DELETE ON control_plane.entitlement_evidence_aliases FOR EACH ROW EXECUTE FUNCTION control_plane.entitlement_alias_source_set_guard();
CREATE FUNCTION control_plane.source_set_exclusive_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,control_plane AS $$ BEGIN
 PERFORM membership_access_source_set_fence(true); RETURN COALESCE(NEW,OLD); END $$;
CREATE TRIGGER membership_access_sources_source_set_insert BEFORE INSERT ON control_plane.membership_access_sources FOR EACH ROW EXECUTE FUNCTION control_plane.source_set_exclusive_guard();
CREATE OR REPLACE FUNCTION control_plane.source_update_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,control_plane AS $$ BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'source identity is immutable and publication transition is invalid'; END IF;
 IF ROW(NEW.id,NEW.source_kind,NEW.reason,NEW.producer_id,NEW.source_event_id,NEW.source_event_digest,NEW.requested_at,NEW.source_effective_at,NEW.mapping_id,NEW.created_xid) IS DISTINCT FROM ROW(OLD.id,OLD.source_kind,OLD.reason,OLD.producer_id,OLD.source_event_id,OLD.source_event_digest,OLD.requested_at,OLD.source_effective_at,OLD.mapping_id,OLD.created_xid) OR NOT ((OLD.publication_state='pending' AND NEW.publication_state='publishing' AND OLD.created_xid<>pg_current_xact_id()) OR (OLD.publication_state='publishing' AND NEW.publication_state='published')) THEN RAISE EXCEPTION 'source identity is immutable and publication transition is invalid'; END IF;
 PERFORM membership_access_source_set_fence(true); RETURN NEW; END $$;

CREATE INDEX identity_sessions_mapping_binding_idx ON control_plane.identity_sessions(mapping_id,binding_key_id,binding_fingerprint);
CREATE INDEX authorization_contexts_mapping_id_idx ON oidc.authorization_contexts(mapping_id,id);
CREATE INDEX entitlements_mapping_id_idx ON control_plane.entitlements(mapping_id,id);

CREATE TABLE control_plane.membership_access_request_operation_links (request_id uuid NOT NULL REFERENCES control_plane.membership_access_requests(id) ON DELETE RESTRICT,operation_id uuid NOT NULL REFERENCES control_plane.membership_access_operations(id) ON DELETE RESTRICT,link_kind text NOT NULL CHECK(link_kind IN ('initial','reconciliation')),created_at timestamptz NOT NULL,PRIMARY KEY(request_id,operation_id),UNIQUE(request_id,link_kind));
CREATE FUNCTION control_plane.request_operation_link_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$ BEGIN IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'request-operation links are append-only'; END IF; RETURN NEW; END $$;
CREATE TRIGGER membership_access_request_operation_links_guard BEFORE UPDATE OR DELETE ON control_plane.membership_access_request_operation_links FOR EACH ROW EXECUTE FUNCTION control_plane.request_operation_link_guard();

ALTER TABLE control_plane.security_audit_events DROP CONSTRAINT security_audit_events_type;
ALTER TABLE control_plane.security_audit_events ADD CONSTRAINT security_audit_events_type CHECK(event_type IN ('login_state_consumed','session_revoked','challenge_consumed','entitlement_decided','policy_activated','membership_access_source_published','membership_access_operation_terminal','membership_access_step_succeeded','membership_access_local_enforced'));
ALTER TABLE control_plane.security_audit_events DROP CONSTRAINT security_audit_events_membership_evidence;
ALTER TABLE control_plane.security_audit_events ADD CONSTRAINT security_audit_events_membership_evidence CHECK((event_type='membership_access_local_enforced' AND outcome='success' AND reason IN ('entitlement_expired','policy_revoked','issuer_revoked','issuer_key_compromise','lost_device') AND source_id IS NOT NULL AND operation_id IS NOT NULL AND step_id IS NULL) OR (event_type='membership_access_source_published' AND outcome='success' AND reason IN ('entitlement_expired','policy_revoked','issuer_revoked','issuer_key_compromise','lost_device') AND source_id IS NOT NULL AND operation_id IS NULL AND step_id IS NULL) OR (event_type='membership_access_operation_terminal' AND outcome='success' AND reason='completed' AND source_id IS NULL AND operation_id IS NOT NULL AND step_id IS NULL) OR (event_type='membership_access_step_succeeded' AND outcome='success' AND reason='completed' AND source_id IS NULL AND operation_id IS NULL AND step_id IS NOT NULL) OR (event_type NOT IN ('membership_access_local_enforced','membership_access_source_published','membership_access_operation_terminal','membership_access_step_succeeded') AND source_id IS NULL AND operation_id IS NULL AND step_id IS NULL));
CREATE UNIQUE INDEX audit_local_enforced_once ON control_plane.security_audit_events(operation_id) WHERE event_type='membership_access_local_enforced';
CREATE FUNCTION control_plane.revocation_no_delete() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$ BEGIN IF TG_OP='DELETE' THEN RAISE EXCEPTION 'revocation operations and steps cannot be deleted'; END IF; RETURN NEW; END $$;
CREATE TRIGGER membership_access_operations_no_delete BEFORE DELETE ON control_plane.membership_access_operations FOR EACH ROW EXECUTE FUNCTION control_plane.revocation_no_delete();
CREATE TRIGGER membership_access_steps_no_delete BEFORE DELETE ON control_plane.membership_access_steps FOR EACH ROW EXECUTE FUNCTION control_plane.revocation_no_delete();

CREATE OR REPLACE FUNCTION control_plane.cleanup_expired(audit_before timestamptz) RETURNS bigint LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,control_plane AS $$ DECLARE removed bigint:=0; affected bigint; BEGIN
 PERFORM pg_advisory_xact_lock(8004); IF audit_before>clock_timestamp()-interval '90 days' THEN RAISE EXCEPTION 'audit retention is 90 days'; END IF;
 DELETE FROM login_states WHERE expires_at<=clock_timestamp(); GET DIAGNOSTICS affected=ROW_COUNT; removed:=removed+affected; DELETE FROM proof_challenges WHERE expires_at<=clock_timestamp(); GET DIAGNOSTICS affected=ROW_COUNT; removed:=removed+affected; DELETE FROM identity_sessions WHERE absolute_expires_at+interval '30 seconds'<=clock_timestamp(); GET DIAGNOSTICS affected=ROW_COUNT; removed:=removed+affected; DELETE FROM idempotency_results WHERE expires_at<=clock_timestamp(); GET DIAGNOSTICS affected=ROW_COUNT; removed:=removed+affected; DELETE FROM jti_uses WHERE retained_until<=clock_timestamp(); GET DIAGNOSTICS affected=ROW_COUNT; removed:=removed+affected; DELETE FROM entitlements e WHERE expires_at+interval '30 seconds'<=clock_timestamp() AND (EXISTS(SELECT 1 FROM membership_access_states st WHERE st.mapping_id=e.mapping_id AND st.barrier_state='suspended') OR NOT EXISTS(SELECT 1 FROM entitlements q WHERE q.mapping_id=e.mapping_id AND q.id<>e.id AND q.status='active' AND q.expires_at>clock_timestamp())); GET DIAGNOSTICS affected=ROW_COUNT; removed:=removed+affected; RETURN removed; END $$;
CREATE OR REPLACE FUNCTION oidc.cleanup_expired(p_now timestamptz) RETURNS bigint LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,oidc AS $$ DECLARE v_now timestamptz:=clock_timestamp(); removed bigint:=0; affected bigint; BEGIN PERFORM pg_advisory_xact_lock(8004); IF p_now IS NULL OR NOT isfinite(p_now) OR p_now>v_now THEN RAISE EXCEPTION 'invalid cleanup cutoff'; END IF; DELETE FROM interaction_csrf WHERE retained_until<=p_now; GET DIAGNOSTICS affected=ROW_COUNT; removed:=removed+affected; DELETE FROM authorization_contexts WHERE retained_until<=p_now; GET DIAGNOSTICS affected=ROW_COUNT; removed:=removed+affected; DELETE FROM provider_artifacts WHERE retained_until<=p_now; GET DIAGNOSTICS affected=ROW_COUNT; RETURN removed+affected; END $$;

CREATE FUNCTION control_plane.enforce_published_source_target(p_source uuid,p_mapping uuid) RETURNS TABLE(operation_id uuid,transition_revision bigint) LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,control_plane,oidc AS $$
DECLARE s membership_access_sources%ROWTYPE; st membership_access_states%ROWTYPE; o uuid; rev bigint; now_at timestamptz; request_id uuid; mas uuid; registry uuid; crypto uuid; BEGIN
 PERFORM pg_advisory_xact_lock_shared(8004); PERFORM membership_access_source_set_fence(false);
 SELECT * INTO s FROM membership_access_sources WHERE id=p_source AND publication_state='published' FOR UPDATE; IF NOT FOUND OR NOT EXISTS(SELECT 1 FROM membership_access_source_targets WHERE source_id=p_source AND mapping_id=p_mapping) THEN RAISE EXCEPTION 'source target is not published'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('dsa-signal-membership-access:v1:'||p_mapping::text,0));
 SELECT * INTO st FROM membership_access_states WHERE mapping_id=p_mapping FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'mapping access state is missing'; END IF;
 SELECT r.id,r.operation_id INTO request_id,o FROM membership_access_requests r WHERE r.source_id=p_source AND r.mapping_id=p_mapping; IF FOUND THEN RETURN QUERY SELECT o,(SELECT transition_revision FROM membership_access_operations WHERE id=o); RETURN; END IF;
 IF st.barrier_state='suspended' AND st.current_operation_id IS NOT NULL AND EXISTS(SELECT 1 FROM membership_access_operations WHERE id=st.current_operation_id AND state<>'completed') THEN INSERT INTO membership_access_requests(id,source_id,mapping_id,operation_id,created_at) VALUES(gen_random_uuid(),p_source,p_mapping,st.current_operation_id,clock_timestamp()) RETURNING operation_id INTO o; INSERT INTO membership_access_request_operation_links(request_id,operation_id,link_kind,created_at) SELECT id,operation_id,'initial',created_at FROM membership_access_requests WHERE source_id=p_source AND mapping_id=p_mapping; RETURN QUERY SELECT o,st.revision; RETURN; END IF;
 now_at:=clock_timestamp(); rev:=st.revision+1; o:=gen_random_uuid();
 INSERT INTO membership_access_operations(id,mapping_id,transition_revision,state,first_effective_at,local_enforced_at,blocked_code) VALUES(o,p_mapping,rev,'blocked',s.source_effective_at,now_at,'missing_external_prerequisites');
 INSERT INTO membership_access_requests(id,source_id,mapping_id,operation_id,created_at) VALUES(gen_random_uuid(),p_source,p_mapping,o,now_at) RETURNING id INTO request_id;
 INSERT INTO membership_access_request_operation_links(request_id,operation_id,link_kind,created_at) VALUES(request_id,o,'initial',now_at);
 INSERT INTO membership_access_mas_targets(id,operation_id,mapping_id,transition_revision,kind) VALUES(gen_random_uuid(),o,p_mapping,rev,'missing') RETURNING id INTO mas;
 INSERT INTO membership_access_registry_snapshots(id,operation_id,mapping_id,transition_revision,kind,expected_room_count) VALUES(gen_random_uuid(),o,p_mapping,rev,'missing',0) RETURNING id INTO registry;
 INSERT INTO membership_access_crypto_capabilities(id,operation_id,mapping_id,transition_revision,kind) VALUES(gen_random_uuid(),o,p_mapping,rev,'missing') RETURNING id INTO crypto;
 INSERT INTO membership_access_steps(id,operation_id,mapping_id,transition_revision,step_kind,state,mas_target_id,error_code) VALUES(gen_random_uuid(),o,p_mapping,rev,'mas_prerequisite','blocked',mas,'missing_mas_binding');
 INSERT INTO membership_access_steps(id,operation_id,mapping_id,transition_revision,step_kind,state,registry_snapshot_id,error_code) VALUES(gen_random_uuid(),o,p_mapping,rev,'registry_prerequisite','blocked',registry,'missing_managed_room_registry');
 INSERT INTO membership_access_steps(id,operation_id,mapping_id,transition_revision,step_kind,state,crypto_capability_id,error_code) VALUES(gen_random_uuid(),o,p_mapping,rev,'crypto_prerequisite','blocked',crypto,'missing_crypto_enforcement');
 UPDATE membership_access_states SET barrier_state='suspended',revision=rev,current_operation_id=o,changed_at=now_at,cause_request_id=request_id WHERE mapping_id=p_mapping;
 UPDATE entitlements SET status='revoked',revoked_at=now_at,reason='revoked',generation=CASE WHEN generation=9223372036854775807 THEN generation ELSE generation+1 END WHERE mapping_id=p_mapping AND status='active';
 UPDATE identity_sessions SET revoked_at=now_at WHERE mapping_id=p_mapping AND revoked_at IS NULL;
 UPDATE authorization_contexts SET revoked_at=now_at WHERE mapping_id=p_mapping AND revoked_at IS NULL;
 UPDATE provider_artifacts a SET revoked_at=now_at WHERE revoked_at IS NULL AND EXISTS(SELECT 1 FROM authorization_contexts c WHERE c.mapping_id=p_mapping AND ((a.grant_key_id,a.grant_fingerprint)=(c.grant_key_id,c.grant_fingerprint) OR (a.session_uid_key_id,a.session_uid_fingerprint)=(c.provider_session_uid_key_id,c.provider_session_uid_fingerprint)));
 INSERT INTO security_audit_events(id,event_type,mapping_id,outcome,reason,occurred_at,source_id,operation_id) VALUES(gen_random_uuid(),'membership_access_local_enforced',p_mapping,'success',s.reason,now_at,p_source,o);
 RETURN QUERY SELECT o,rev; END $$;
REVOKE ALL ON FUNCTION control_plane.enforce_published_source_target(uuid,uuid) FROM PUBLIC;
